<script>(()=>{const nav=document.querySelector('[data-e802-nav]');document.querySelector('[data-e802-toggle]')?.addEventListener('click',()=>nav?.classList.toggle('is-open'));document.querySelectorAll('[data-e802-tab]').forEach(btn=>btn.addEventListener('click',()=>{const root=btn.closest('[data-e802-tabs]');root?.querySelectorAll('[data-e802-tab]').forEach(x=>x.classList.remove('is-active'));btn.classList.add('is-active')}));})();</script>
